    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c"), ("pos_x", "pos_y")):
                if a in v and b in v:
                    return v[a], v[b]
            p = v.get("pos") or v.get("position") or v.get("loc") or v.get("location")
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return p[0], p[1]
        return None

    me = pos(observation.get("self_position")) or pos(observation.get("self")) or (0, 0)
    op = pos(observation.get("opponent_position")) or pos(observation.get("opponent")) or (w - 1, h - 1)
    rx, ry = me[0], me[1]
    best = None

    res = observation.get("resources") or []
    if isinstance(res, dict):
        res = res.values()

    for r in res:
        p = pos(r)
        if p is None:
            continue
        x, y = p
        d = abs(x - rx) + abs(y - ry)
        s = d * 10 + abs(x - op[0]) + abs(y - op[1])
        if best is None or s < best[0] or (s == best[0] and (x, y) < best[1]):
            best = (s, (x, y))

    if best:
        tx, ty = best[1]
    else:
        tx, ty = (0 if rx > w // 2 else w - 1), (0 if ry > h // 2 else h - 1)

    dx = 0 if tx == rx else (1 if tx > rx else -1)
    dy = 0 if ty == ry else (1 if ty > ry else -1)

    obs = set()
    for k in ("obstacles", "self_path", "opponent_path"):
        v = observation.get(k) or []
        if isinstance(v, dict):
            v = v.values()
        for a in v:
            p = pos(a)
            if p is not None:
                obs.add((p[0], p[1]))

    if (rx + dx, ry + dy) in obs:
        if dx and (rx, ry + (1 if ty > ry else -1)) not in obs:
            dx, dy = 0, (1 if ty > ry else -1)
        elif dy and (rx + (1 if tx > rx else -1), ry) not in obs:
            dx, dy = (1 if tx > rx else -1), 0
        else:
            for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)):
                nx, ny = rx + a, ry + b
                if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obs:
                    dx, dy = a, b
                    break

    return [int(dx), int(dy)]

